'use strict';

var baseControllers = require('@toruslabs/base-controllers');
var auth = require('@web3auth/auth');

function createChainIdMiddleware(chainId) {
  return ({
    request,
    next
  }) => {
    if (request.method === "chainId") return chainId;
    return next(request);
  };
}
function createProviderConfigMiddleware(providerConfig) {
  return ({
    request,
    next
  }) => {
    if (request.method === "provider_config") return providerConfig;
    return next(request);
  };
}
function createJsonRpcClient(providerConfig) {
  const {
    chainId,
    rpcTarget
  } = providerConfig;
  const engine = auth.JRPCEngineV2.create({
    middleware: [createChainIdMiddleware(chainId), createProviderConfigMiddleware(providerConfig), baseControllers.createFetchMiddleware({
      rpcTarget
    })]
  });
  const networkMiddleware = engine.asMiddleware();
  return {
    networkMiddleware
  };
}

exports.createJsonRpcClient = createJsonRpcClient;
